import { useDroppable } from "@dnd-kit/core";

import { cn } from "../../lib/cn";
import type { GroupEdgeDropData, PaneEdgeDropData, TabDropEdge } from "./tabDragTypes";

type SplitEdgeDropData = GroupEdgeDropData | PaneEdgeDropData;

type SplitEdgeDropZoneProps = {
  id: string;
  data: SplitEdgeDropData;
  edge: TabDropEdge;
  testId: string;
  groupId?: string;
  tabId?: string;
  leafId?: string;
};

/**
 * Shared split-edge target used by both tab drags and pane-handle drags.
 * Drag source only changes the command resolved after drop; target geometry and
 * visual feedback intentionally follow the same tab-drag contract.
 */
export function SplitEdgeDropZone({
  id,
  data,
  edge,
  testId,
  groupId,
  tabId,
  leafId,
}: SplitEdgeDropZoneProps) {
  const { setNodeRef, isOver } = useDroppable({ id, data });

  return (
    <div
      ref={setNodeRef}
      aria-hidden="true"
      data-testid={testId}
      data-split-edge-drop-zone="true"
      data-dnd-type={data.type}
      data-drop-edge={edge}
      data-drop-group-id={groupId}
      data-tab-id={tabId}
      data-leaf-id={leafId}
      className={cn(
        "pointer-events-none absolute z-40 transition-colors",
        edgeHitTargetClass(edge),
        isOver && "border-2 border-primary bg-primary/20 backdrop-blur-[1px]",
      )}
    >
      {isOver ? (
        <span
          data-testid="split-edge-drop-feedback"
          className="absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm"
        >
          New split
        </span>
      ) : null}
    </div>
  );
}

export function edgeHitTargetClass(edge: TabDropEdge): string {
  switch (edge) {
    case "left":
      return "inset-y-0 left-0 w-[20%]";
    case "right":
      return "inset-y-0 right-0 w-[20%]";
    case "top":
      return "left-[20%] right-[20%] top-0 h-[20%]";
    case "bottom":
      return "bottom-0 left-[20%] right-[20%] h-[20%]";
  }
}

import type { TabDropEdge } from "./tabDragTypes";
import { SplitEdgeDropZone } from "./SplitEdgeDropZone";

const EDGES: TabDropEdge[] = ["left", "right", "top", "bottom"];

type PaneEdgeDropZonesProps = {
  tabId: string;
  leafId: string;
};

export function PaneEdgeDropZones({ tabId, leafId }: PaneEdgeDropZonesProps) {
  return (
    <>
      {EDGES.map((edge) => (
        <SplitEdgeDropZone
          key={edge}
          id={`pane-edge:${tabId}:${leafId}:${edge}`}
          data={{ type: "pane-edge", tabId, leafId, edge }}
          edge={edge}
          testId="pane-edge-drop-zone"
          tabId={tabId}
          leafId={leafId}
        />
      ))}
    </>
  );
}

import { useDroppable } from "@dnd-kit/core";
import type { ReactNode } from "react";

import { cn } from "../../lib/cn";
import type { TabDropEdge } from "./tabDragTypes";

type TabGroupDropSurfaceProps = {
  groupId: string;
  children: ReactNode;
};

export function TabGroupDropSurface({ groupId, children }: TabGroupDropSurfaceProps) {
  const body = useDroppable({
    id: `group-body:${groupId}`,
    data: { type: "group-body", groupId },
  });

  return (
    <div
      ref={body.setNodeRef}
      data-tab-group-body-id={groupId}
      data-dnd-type="group-body"
      className="relative min-h-0 flex-1 overflow-hidden bg-terminal"
    >
      {children}
      <TabGroupEdgeDropZone groupId={groupId} edge="left" />
      <TabGroupEdgeDropZone groupId={groupId} edge="right" />
      <TabGroupEdgeDropZone groupId={groupId} edge="top" />
      <TabGroupEdgeDropZone groupId={groupId} edge="bottom" />
    </div>
  );
}

function TabGroupEdgeDropZone({ groupId, edge }: { groupId: string; edge: TabDropEdge }) {
  const { setNodeRef, isOver } = useDroppable({
    id: `group-edge:${groupId}:${edge}`,
    data: { type: "group-edge", groupId, edge },
  });

  return (
    <div
      ref={setNodeRef}
      aria-hidden="true"
      data-testid="tab-group-edge-drop-zone"
      data-drop-edge={edge}
      data-drop-group-id={groupId}
      data-dnd-type="group-edge"
      className={cn(
        "pointer-events-none absolute z-40 transition-colors",
        edge === "left" && "inset-y-0 left-0 w-[20%]",
        edge === "right" && "inset-y-0 right-0 w-[20%]",
        edge === "top" && "left-[20%] right-[20%] top-0 h-[20%]",
        edge === "bottom" && "bottom-0 left-[20%] right-[20%] h-[20%]",
        isOver && "border-2 border-primary bg-primary/20 backdrop-blur-[1px]",
      )}
    >
      {isOver ? (
        <span className="absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm">
          New split
        </span>
      ) : null}
    </div>
  );
}

import { useRef, useEffect } from "react";
import { setBrowserBounds, setBrowserVisible } from "../lib/browserTauri";
import { BrowserToolbar } from "./BrowserToolbar";
import type { BrowserTab } from "../lib/types";

interface BrowserPaneProps {
  tab: BrowserTab;
  visible?: boolean;
  onNavigate: (url: string) => void;
  onReload: () => void;
}

export function BrowserPane({ tab, visible = true, onNavigate, onReload }: BrowserPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const updateVisibility = (nextVisible: boolean) => {
      void setBrowserVisible(tab.browserId, nextVisible).catch(() => undefined);
    };

    const updateBounds = () => {
      if (!visible) {
        updateVisibility(false);
        return;
      }

      const rect = el.getBoundingClientRect();
      void setBrowserBounds(tab.browserId, {
        x: rect.x,
        y: rect.y,
        width: rect.width,
        height: rect.height,
      }).catch(() => undefined);
      updateVisibility(true);
    };

    updateBounds();

    const resizeObserver = new ResizeObserver(() => {
      updateBounds();
    });

    resizeObserver.observe(el);
    window.addEventListener("resize", updateBounds);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", updateBounds);
      // Native child webviews outlive React DOM nodes; cleanup also covers Fast Refresh remounts.
      updateVisibility(false);
    };
  }, [tab.browserId, visible]);

  return (
    <div className="flex flex-col w-full h-full bg-background overflow-hidden">
      <BrowserToolbar tab={tab} onNavigate={onNavigate} onReload={onReload} />
      <div
        ref={containerRef}
        data-testid="browser-viewport"
        className="flex-1 w-full bg-card relative"
      />
    </div>
  );
}

