function TabGroupView({
  groupId,
  layout,
  groups,
  sessions,
  leadingSpacer,
  onActivateTab,
  onCloseTab,
  onCloseOtherTabs,
  onCloseTabsToRight,
  onCloseTabsToLeft,
  onRenameTab,
  onToggleTabPin,
  onAddTab,
  onAddBrowserTab,
  onAddMarkdown,
  onAddMobileEmulator,
  onOpenSettings,
  agents,
  onLaunchAgent,
  defaultAgentId,
  onNavigateBrowserTab,
