// ui/src/components/TerminalSplitView.realDropPayload.runtime.test.tsx
import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

const dndHarness = vi.hoisted(() => ({
  props: null as null | {
    onDragStart?: (event: any) => void;
    onDragEnd?: (event: any) => void;
  },
  registeredDroppables: new Map<string, any>(),
}));

vi.mock("@dnd-kit/core", () => ({
  DndContext: (props: any) => {
    dndHarness.props = props;
    return props.children;
  },
  DragOverlay: ({ children }: any) => children,
  KeyboardSensor: function KeyboardSensor() {},
  PointerSensor: function PointerSensor() {},
  pointerWithin: vi.fn(() => []),
  useDraggable: (args: any) => ({
    setNodeRef: vi.fn(),
    attributes: { "data-draggable-id": args?.id },
    listeners: {},
    isDragging: false,
  }),
  useDroppable: (args: any) => {
    dndHarness.registeredDroppables.set(args.id, args.data);
    return {
      setNodeRef: vi.fn(),
      isOver: false,
    };
  },
  useSensor: vi.fn(() => ({})),
  useSensors: vi.fn(() => []),
}));

vi.mock("./TerminalPane", () => ({
  TerminalPane: () => <div data-testid="terminal-pane" />,
}));

import type { LayoutState, TerminalSession, TerminalTab } from "../lib/types";
import { TerminalSplitView } from "./TerminalSplitView";

afterEach(() => {
  cleanup();
  dndHarness.props = null;
  dndHarness.registeredDroppables.clear();
});

describe("TerminalSplitView end-to-end drop handler payload delivery", () => {
  it("delivers correct payload to onMoveTabToSplit when dropping tab on right pane edge", () => {
    const tabSource: TerminalTab = { kind: "terminal", id: "tab-src", label: "Source", sessionId: "s1" };
    const tabTarget: TerminalTab = { kind: "terminal", id: "tab-tgt", label: "Target", sessionId: "s2" };

    const layout: LayoutState = {
      tabs: [tabSource, tabTarget],
      activeTabId: "tab-tgt",
      tabGroups: {
        "g-1": { id: "g-1", tabIds: ["tab-src", "tab-tgt"], activeTabId: "tab-tgt" },
      },
      tabGroupLayout: { type: "group", groupId: "g-1" },
      focusedGroupId: "g-1",
      layoutsByTabId: {
        "tab-tgt": {
          root: { type: "leaf", leafId: "leaf-tgt" },
          activeLeafId: "leaf-tgt",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-tgt": "s2" },
        },
      },
    };

    const onMoveTabToSplit = vi.fn();

    render(
      <TerminalSplitView
        layout={layout}
        sessions={{ s1: { id: "s1" } as any, s2: { id: "s2" } as any }}
        onMoveTabToSplit={onMoveTabToSplit}
      />,
    );

    // Verify pane edge droppable is registered in DOM and harness
    const targetDroppableId = "pane-edge:tab-tgt:leaf-tgt:right";
    const overData = dndHarness.registeredDroppables.get(targetDroppableId);
    expect(overData).toEqual({
      type: "pane-edge",
      tabId: "tab-tgt",
      leafId: "leaf-tgt",
      edge: "right",
    });

    // Trigger drag start with source tab
    dndHarness.props!.onDragStart!({
      active: {
        data: {
          current: {
            type: "tab",
            tabId: "tab-src",
            groupId: "g-1",
            index: 0,
          },
        },
      },
    });

    // Trigger drop onto the resolved droppable data
    dndHarness.props!.onDragEnd!({
      over: {
        id: targetDroppableId,
        data: {
          current: overData,
        },
      },
    });

    // Concrete payload assertion: moves tab-src to split with target pane info
    expect(onMoveTabToSplit).toHaveBeenCalledTimes(1);
    expect(onMoveTabToSplit).toHaveBeenCalledWith(
      "tab-src",
      "g-1",
      "horizontal",
      "second",
      { tabId: "tab-tgt", leafId: "leaf-tgt" },
    );
  });
});
